import React, { useState } from 'react';
import Sidebar from '../components/Sidebar';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard({ handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');
  const [showDropdown, setShowDropdown] = useState(false); // Logout පේන්න/හංගන්න State එකක්

  const [stats] = useState({
    totalStudents: '1,250',
    totalTeachers: '45',
    activeClasses: '120',
    inactiveStudents: '25'
  });

  const [growthData] = useState({
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#15803d',
      backgroundColor: 'rgba(21, 128, 61, 0.1)',
      tension: 0.4,
      fill: true
    }]
  });

  return (
    <div style={{ 
      display: 'flex', 
      width: '100%', 
      backgroundColor: '#f8fafc', 
      minHeight: '100vh', 
      fontFamily: 'sans-serif' 
    }}>
      
      {/* Sidebar එක */}
      <Sidebar currentSubPage={currentSubPage} setCurrentSubPage={setCurrentSubPage} onLogoutClick={handleLogout} />

      {/* දකුණු පැත්තේ ප්‍රධාන කොටස */}
      <div style={{ flex: 1, padding: '30px', display: 'flex', flexDirection: 'column', gap: '25px', position: 'relative' }}>
        
        {/* ---- TOP NAVIGATION BAR (👤 admin තියෙන තැන) ---- */}
        <div style={{ 
          display: 'flex', 
          justifyContent: 'flex-end', 
          alignItems: 'center', 
          paddingBottom: '15px',
          borderBottom: '1px solid #e2e8f0',
          position: 'relative'
        }}>
          {/* admin Profile ක්ලික් කරපුහාම Dropdown එක toggle වෙනවා */}
          <div 
            onClick={() => setShowDropdown(!showDropdown)}
            style={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: '10px', 
              cursor: 'pointer',
              padding: '8px 15px',
              borderRadius: '8px',
              backgroundColor: '#ffffff',
              boxShadow: '0 2px 5px rgba(0,0,0,0.05)',
              userSelect: 'none'
            }}
          >
            <span style={{ fontSize: '18px' }}>👤</span>
            <span style={{ fontSize: '15px', fontWeight: '600', color: '#1e293b' }}>admin</span>
          </div>

          {/* ---- මෙන්න ඔයා ඉල්ලපු විදිහට admin ලේබල් එකට කෙලින්ම පල්ලෙහායින් වැටෙන Logout බටන් එක ---- */}
          {showDropdown && (
            <div 
              onClick={handleLogout}
              style={{ 
                position: 'absolute',
                top: '50px',
                right: '0',
                backgroundColor: '#ffffff',
                border: '1px solid #e2e8f0',
                borderRadius: '8px',
                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                padding: '10px 20px',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '10px',
                zIndex: 100,
                color: '#dc2626',
                fontWeight: 'bold',
                fontSize: '14px',
                transition: 'background 0.2s'
              }}
              onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fef2f2'}
              onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#ffffff'}
            >
              <span>🚪</span>
              <span>Logout</span>
            </div>
          )}
        </div>

        {/* ---- PAGES CONDITIONAL RENDERING ---- */}
        {currentSubPage === 'Overview' && (
          <>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px' }}>
              {[
                { t: 'Total Students', v: stats.totalStudents, i: '👨‍🎓' },
                { t: 'Total Teachers', v: stats.totalTeachers, i: '👩‍🏫' },
                { t: 'Active Classes', v: stats.activeClasses, i: '🏫' },
                { t: 'Inactive Students', v: stats.inactiveStudents, i: '⚠️' }
              ].map((card, i) => (
                <div key={i} style={{ background: '#ffffff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', border: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <p style={{ color: '#64748b', fontSize: '13px', fontWeight: '500', margin: '0 0 6px 0' }}>{card.t}</p>
                    <h2 style={{ margin: 0, color: '#1e293b', fontSize: '26px', fontWeight: '700' }}>{card.v}</h2>
                  </div>
                  <span style={{ fontSize: '24px', opacity: 0.7 }}>{card.i}</span>
                </div>
              ))}
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '25px' }}>
              <div style={{ background: '#ffffff', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', border: '1px solid #f1f5f9' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                  <h3 style={{ margin: 0, fontSize: '15px', color: '#1e293b', fontWeight: '600' }}>Enrollment Growth & Revenue Overview</h3>
                  <span style={{ backgroundColor: '#e0f2fe', color: '#0369a1', padding: '5px 12px', borderRadius: '20px', fontSize: '12px', fontWeight: '600' }}>Total Revenue: LKR 450,000</span>
                </div>
                <div style={{ width: '100%', height: '240px' }}>
                  <Line data={growthData} options={{ responsive: true, maintainAspectRatio: false }} />
                </div>
              </div>

              <div style={{ background: '#ffffff', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', border: '1px solid #f1f5f9' }}>
                <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b', fontWeight: '600' }}>Student Status At-A-Glance</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                  {[
                    { name: 'Ruwan Name', status: 'Active', bg: '#22c55e' },
                    { name: 'John Name', status: 'Active', bg: '#22c55e' },
                    { name: 'Sama Name', status: 'Inactive', bg: '#ef4444' },
                    { name: 'Ramn Name', status: 'Active', bg: '#22c55e' }
                  ].map((student, i) => (
                    <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderBottom: '1px solid #f1f5f9' }}>
                      <span style={{ fontSize: '14px', color: '#334155', fontWeight: '500' }}>{student.name}</span>
                      <span style={{ backgroundColor: student.bg, color: '#ffffff', padding: '4px 12px', borderRadius: '6px', fontSize: '11px', fontWeight: '600' }}>{student.status}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div style={{ background: '#ffffff', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', border: '1px solid #f1f5f9' }}>
              <h3 style={{ margin: '0 0 20px 0', fontSize: '15px', color: '#1e293b', fontWeight: '600' }}>Upcoming Class Schedule</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid #f1f5f9' }}>
                    <th style={{ padding: '10px', color: '#64748b' }}>Time</th>
                    <th style={{ padding: '10px', color: '#64748b' }}>Sun</th>
                    <th style={{ padding: '10px', color: '#64748b' }}>Mon</th>
                    <th style={{ padding: '10px', color: '#64748b' }}>Wed</th>
                    <th style={{ padding: '10px', color: '#64748b' }}>Thu</th>
                    <th style={{ padding: '10px', color: '#64748b' }}>Fri</th>
                  </tr>
                </thead>
                <tbody>
                  {[
                    { time: '10:00', sun: '', mon: 'Math 101', wed: '', thu: '', fri: '' },
                    { time: '11:00', sun: 'Wedneddiel', mon: '', wed: 'Science', thu: 'English Lit', fri: '' },
                    { time: '2:00', sun: '', mon: '', wed: '', thu: '', fri: 'History Class' }
                  ].map((row, i) => (
                    <tr key={i} style={{ borderBottom: '1px solid #f1f5f9' }}>
                      <td style={{ padding: '15px 10px', fontWeight: '600', color: '#475569' }}>{row.time}</td>
                      <td style={{ padding: '5px' }}>{row.sun && <span style={{ backgroundColor: '#15803d', color: '#fff', padding: '6px 12px', borderRadius: '6px', fontSize: '12px' }}>{row.sun}</span>}</td>
                      <td style={{ padding: '5px' }}>{row.mon && <span style={{ backgroundColor: '#166534', color: '#fff', padding: '6px 12px', borderRadius: '6px', fontSize: '12px' }}>{row.mon}</span>}</td>
                      <td style={{ padding: '5px' }}>{row.wed && <span style={{ backgroundColor: '#f59e0b', color: '#fff', padding: '6px 12px', borderRadius: '6px', fontSize: '12px' }}>{row.wed}</span>}</td>
                      <td style={{ padding: '5px' }}>{row.thu && <span style={{ backgroundColor: '#10b981', color: '#fff', padding: '6px 12px', borderRadius: '6px', fontSize: '12px' }}>{row.thu}</span>}</td>
                      <td style={{ padding: '5px' }}>{row.fri && <span style={{ backgroundColor: '#8b5cf6', color: '#fff', padding: '6px 12px', borderRadius: '6px', fontSize: '12px' }}>{row.fri}</span>}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}

        {currentSubPage === 'Students' && (
          <div style={{ background: '#ffffff', padding: '30px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
            <h2>👨‍🎓 Student Management</h2>
            <p style={{ color: '#64748b' }}>Here you can add, view, and manage all registered students.</p>
          </div>
        )}

        {currentSubPage === 'Teachers & Classes' && (
          <div style={{ background: '#ffffff', padding: '30px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
            <h2>🏫 Teachers & Classes</h2>
            <p style={{ color: '#64748b' }}>Manage teacher profiles and assign them to specific subject classes.</p>
          </div>
        )}

        {currentSubPage === 'Reports' && (
          <div style={{ background: '#ffffff', padding: '30px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
            <h2>📋 Academic Reports</h2>
            <p style={{ color: '#64748b' }}>View attendance reports, student performance, and exam details.</p>
          </div>
        )}

        {currentSubPage === 'Settings' && (
          <div style={{ background: '#ffffff', padding: '30px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
            <h2>⚙️ System Settings</h2>
            <p style={{ color: '#64748b' }}>Configure system variables, database options, and user access levels.</p>
          </div>
        )}

      </div>
    </div>
  );
}
